/* Markup: <div class="fx-orbit" role="img" aria-label="ORBIT"><b aria-hidden="true" style="--i:0">O</b><b aria-hidden="true" style="--i:1">R</b><b aria-hidden="true" style="--i:2">B</b><b aria-hidden="true" style="--i:3">I</b><b aria-hidden="true" style="--i:4">T</b></div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 44 Orbitals */
.fx-orbit {
  font: 600 30px/1.1 JetBrains Mono, monospace;
  letter-spacing: .08em;
  color: var(--ink);
  display: inline-flex;
}
.fx-orbit b {
  font-weight: inherit;
  display: inline-block;
  transform-origin: 50% 120%;
  animation: fx-orbit 2.8s cubic-bezier(.45, 0, .2, 1) infinite;
  animation-delay: calc(var(--i) * -.18s);
}
.fx-orbit b:nth-child(odd) {
  color: var(--ink-3);
}
.fx-orbit b:nth-child(3n) {
  color: var(--ink-2);
}
@keyframes fx-orbit {
  0%,to {
    transform: translate(0) rotate(0);
  }
  35% {
    transform: translate(5px, -13px) rotate(16deg);
  }
  70% {
    transform: translate(-5px, 7px) rotate(-10deg);
  }
}
